import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"ADR-0011: Why P0 Ships Only Process and Exec Probes","description":"","frontmatter":{},"headers":[],"relativePath":"adr/ADR-0011-why-p0-only-process-exec-probes.md","filePath":"adr/ADR-0011-why-p0-only-process-exec-probes.md","lastUpdated":1793381793000}`),a={name:`adr/ADR-0011-why-p0-only-process-exec-probes.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="adr-0011-why-p0-ships-only-process-and-exec-probes" tabindex="-1">ADR-0011: Why P0 Ships Only Process and Exec Probes <a class="header-anchor" href="#adr-0011-why-p0-ships-only-process-and-exec-probes" aria-label="Permalink to “ADR-0011: Why P0 Ships Only Process and Exec Probes”">​</a></h1><ul><li>Status: Accepted</li><li>Date: 2026-10-31</li><li>Related: docs/guide/probe-survey.md §26.11, roadmap P0</li></ul><h2 id="background" tabindex="-1">Background <a class="header-anchor" href="#background" aria-label="Permalink to “Background”">​</a></h2><p>Probe types are unlimited (survey §26 lists 20+), but P0 must prove the architecture: probe → normalization → diagnosis → dependency check → recovery → independent verification → persistence → audit, all correct. Spreading across 20 probe types makes each shallow.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>P0 implements only Process (pid file + liveness) and Exec (controlled command + timeout + output cap), proving the full loop and acceptance with them; other probe types are added in the survey §26.11 recommended order, each with independent tests, cross-platform semantics (Linux/Windows), and normalization rules (connection refused ≠ timeout, Unreachable ≠ Unhealthy), one tick per probe.</p><h2 id="alternatives" tabindex="-1">Alternatives <a class="header-anchor" href="#alternatives" aria-label="Permalink to “Alternatives”">​</a></h2><ul><li><strong>Implement all probe types at once</strong>: spread too thin; normalization rules never polished per-type — false positives and negatives only surface in real deployments.</li><li><strong>Only the Exec universal probe</strong>: loses normalization (command output is not structured health state), cannot support verification and dependency conditions.</li></ul><h2 id="pros-and-cons" tabindex="-1">Pros and Cons <a class="header-anchor" href="#pros-and-cons" aria-label="Permalink to “Pros and Cons”">​</a></h2><p>Pros: loop quality first; each probe type has independent semantic boundaries and tests (now 13 high-priority items done, 174/174 green); clear extension template. Cons: fewer monitorable objects early (users use Exec as fallback).</p><h2 id="follow-up-impact" tabindex="-1">Follow-up Impact <a class="header-anchor" href="#follow-up-impact" aria-label="Permalink to “Follow-up Impact”">​</a></h2><ul><li>probe-survey §26.11 order is the roadmap; each probe type is one module (icmp.rs/database.rs…).</li><li>New probes must provide: normalization rules, timeout/permission semantics, Windows behavior (cfg or cross-check).</li></ul>`,12)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};